def count_components_by_color(grid):
    colors = set()
    for r in range(14):
        for c in range(19):
            if grid[r][c] != 9:
                colors.add(grid[r][c])

    counts = {}
    visited = [[False]*19 for _ in range(14)]

    for color in sorted(colors):
        count = 0
        for r in range(14):
            for c in range(19):
                if grid[r][c] == color and not visited[r][c]:
                    stack = [(r,c)]
                    visited[r][c] = True
                    while stack:
                        cr, cc = stack.pop()
                        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                            nr, nc = cr+dr, cc+dc
                            if 0 <= nr < 14 and 0 <= nc < 19:
                                if grid[nr][nc] == color and not visited[nr][nc]:
                                    visited[nr][nc] = True
                                    stack.append((nr, nc))
                    count += 1
        counts[color] = count

    return counts

